"""C2PA / Content Credentials inspection via the official c2pa-python library."""
from __future__ import annotations

import json

from ..core.claims import NotRun, Polarity, Status, Strength
from .base import Analyzer, Ctx, register

AI_SOURCE_TYPES = {
    "trainedAlgorithmicMedia": "fully generated by a trained AI model",
    "compositeWithTrainedAlgorithmicMedia": "a composite that includes AI-generated elements",
    "algorithmicMedia": "generated algorithmically (not from a camera)",
    "compositeSynthetic": "a composite including synthetic elements",
}
CAPTURE_SOURCE_TYPES = {"digitalCapture": "captured by a camera/sensor",
                        "computationalCapture": "captured with computational photography"}

try:
    import c2pa  # type: ignore

    _C2PA_VERSION = c2pa.sdk_version()
    try:  # never auto-fetch remote manifests (outward network call) without consent
        c2pa.load_settings(json.dumps({"verify": {"remote_manifest_fetch": False}}))
    except Exception:  # noqa: BLE001
        pass
except Exception:  # noqa: BLE001
    c2pa = None
    _C2PA_VERSION = None


def _walk_actions(manifest: dict) -> list[dict]:
    out = []
    for a in manifest.get("assertions", []) or []:
        if str(a.get("label", "")).startswith("c2pa.actions"):
            out.extend((a.get("data") or {}).get("actions", []) or [])
    return out


@register
class C2PAAnalyzer(Analyzer):
    order = 20
    name = "c2pa"
    version = "1.0"
    title = "C2PA / Content Credentials"

    def available(self):
        if c2pa is None:
            return NotRun(component=self.name, reason="c2pa-python not installed",
                          how_to_enable="uv sync --extra provenance")
        return None

    def run(self, ctx: Ctx):
        reader = None
        try:
            reader = c2pa.Reader.try_create(str(ctx.path))
        except Exception as e:  # noqa: BLE001
            ctx.claim("c2pa", f"C2PA data present but could not be parsed ({type(e).__name__})", Status.UNKNOWN,
                      limitations="A damaged or unsupported manifest cannot be validated.", data={"error": str(e)[:300]})
            return
        if reader is None:
            ctx.claim("c2pa", "No C2PA / Content Credentials manifest found", Status.UNKNOWN,
                      why="The file carries no embedded provenance manifest.",
                      limitations="Absence does NOT indicate authenticity: most media has no C2PA, and platforms strip "
                                  "manifests on re-upload. Many generators do not sign their output.",
                      confirm="Check earlier copies — the earliest discovered copy is the most likely to retain a manifest.")
            return
        with reader:
            store = json.loads(reader.json())
            state = reader.get_validation_state() or "Unknown"
            results = reader.get_validation_results() or {}
            active = reader.get_active_manifest() or {}
            embedded = reader.is_embedded()
        ctx.shared["c2pa"] = {"state": state, "active": active}
        gen = active.get("claim_generator") or ", ".join(
            f"{g.get('name', '')} {g.get('version', '')}".strip() for g in active.get("claim_generator_info", []) or [])
        sig = active.get("signature_info") or {}
        issuer, sig_time = sig.get("issuer") or sig.get("common_name"), sig.get("time")
        valid = state.lower() in ("valid", "trusted")
        status = Status.VERIFIED if valid else Status.UNKNOWN
        ctx.claim("c2pa",
                  f"C2PA manifest present ({'embedded' if embedded else 'remote'}); validation state: {state}; "
                  f"claim generator: {gen or 'not stated'}; signed by: {issuer or 'unknown'}",
                  status, strength=Strength.STRONG if valid else Strength.WEAK,
                  why=("A cryptographically valid manifest binds the provenance statements to these exact bytes."
                       if valid else "The manifest exists but did not validate; its statements cannot be relied upon."),
                  limitations="A valid signature proves who signed the manifest and that the bytes are unchanged since "
                              "— not that the signer's statements are true. 'Valid' is not 'Trusted' unless the signer's "
                              "certificate chains to a trust list.",
                  data={"state": state, "generator": gen, "issuer": issuer, "signed_at": sig_time,
                        "validation": results, "title": active.get("title")})
        for act in _walk_actions(active):
            dst = str(act.get("digitalSourceType", ""))
            key = dst.rsplit("/", 1)[-1]
            when = act.get("when")
            agent = (act.get("softwareAgent") or {})
            agent = agent.get("name") if isinstance(agent, dict) else agent
            if key in AI_SOURCE_TYPES:
                ctx.claim("c2pa", f"C2PA action '{act.get('action')}' declares the content {AI_SOURCE_TYPES[key]}"
                          + (f" (software agent: {agent})" if agent else ""),
                          status, strength=Strength.STRONG if valid else Strength.WEAK,
                          polarity=Polarity.SUPPORTS_MANIPULATION,
                          why="The signer explicitly declared an AI digital source type in the provenance record.",
                          limitations="Relies on the signing tool's honesty; it is the strongest available "
                                      "generation-tool signal when the signature validates.",
                          data={"action": act.get("action"), "digitalSourceType": dst, "softwareAgent": agent, "when": when,
                                "generator_family": agent or gen})
            elif key in CAPTURE_SOURCE_TYPES:
                ctx.claim("c2pa", f"C2PA declares the content {CAPTURE_SOURCE_TYPES[key]}", status,
                          strength=Strength.MODERATE if valid else Strength.WEAK, polarity=Polarity.SUPPORTS_AUTHENTIC,
                          limitations="Declares the capture origin; later edits may be listed as further actions.",
                          data={"action": act.get("action"), "digitalSourceType": dst, "when": when})
        ingredients = active.get("ingredients") or []
        if ingredients:
            ctx.claim("c2pa", f"C2PA lists {len(ingredients)} ingredient(s): "
                      + "; ".join(str(i.get("title")) for i in ingredients[:5]), status, strength=Strength.WEAK,
                      data={"ingredients": [{"title": i.get("title"), "format": i.get("format"),
                                             "relationship": i.get("relationship")} for i in ingredients]})
        ctx.artifact("c2pa", "C2PA manifest store", json.dumps(store, indent=2).encode(), mime="application/json")
